const titleCaseService=(value:string)=>value.replace(/\b[a-z][a-z+]*\b/g,word=>word[0].toUpperCase()+word.slice(1));
const normalizeEntitlements=(stored:typeof initialEntitlements)=>{const normalized=stored.map(e=>{const items=e.items.map(i=>({...i,label:titleCaseService(i.label)}));if(e.name==="Runner Recovery Pack"){const sports=items.find(i=>i.label==="Sports Massage"),stretch=items.find(i=>i.label==="Assisted Stretching"),sportsUsed=Math.max(0,(sports?.total??4)-(sports?.remaining??4)),stretchUsed=Math.max(0,(stretch?.total??2)-(stretch?.remaining??2));return{...e,items:[{label:"Sports Massage",remaining:Math.max(0,4-sportsUsed),total:4},{label:"Assisted Stretching",remaining:Math.max(0,2-stretchUsed),total:2}]}}if(e.name==="Event Ready Pack"||e.name==="Look Your Best Pack"||e.name==="Looking Snatched Pack"){const remaining=(label:string)=>{const item=items.find(i=>i.label===label),used=Math.max(0,(item?.total??1)-(item?.remaining??1));return Math.max(0,1-used)};return{...e,name:"Looking Snatched Pack",items:["Facial","Facial Workout Massage","Lymphatic Drainage Massage"].map(label=>({label,remaining:remaining(label),total:1}))}}if(e.name==="Full Body Reset Pack"||e.name==="Salu Essentials Pack"){const remaining=(label:string,total:number)=>{const item=items.find(i=>i.label===label),used=Math.max(0,(item?.total??total)-(item?.remaining??total));return Math.max(0,total-used)};return{...e,name:"Salu Essentials Pack",items:["Deep Tissue Massage","Lymphatic Drainage Massage","Acupuncture"].map(label=>({label,remaining:remaining(label,2),total:2}))}}return{...e,items}});return normalized.filter((e,index,all)=>all.findIndex(item=>item.name===e.name)===index)};
const atlasResponse=(prompt:string)=>atlasReplies.find(reply=>reply.match.test(prompt))?.text||"I can help with that. I’ve considered your Miami location, timing and available Credits, and pulled together a few thoughtful options.";
const atlasMatches=(prompt:string)=>{const groups:[RegExp,string[]][]=[[/emergency|chest pain|can.t breathe|faint/i,[]],[/protein|nutrition|diet|meal/i,["dietitian"]],[/iv|drip|nad/i,["iv","nad"]],[/blood|lab|test/i,["blood-draw"]],[/acupunct/i,["acupuncture"]],[/stretch|mobility/i,["stretch"]],[/wedding|event|glow|snatch/i,["facial","facial-workout","lymphatic-massage"]],[/weight|muscle|glp/i,["blood-draw","lymphatic-massage","facial-workout"]],[/puffy|dehydrat|flight|travel|lymph/i,["lymphatic-massage","facial","stretch"]],[/marathon|run|training|recovery/i,["sports-massage","stretch","training"]],[/massage|sore|tight|knot/i,["deep-tissue","sports-massage","lymphatic-massage"]]];const ids=groups.find(([re])=>re.test(prompt))?.[1];if(ids)return ids.map(id=>services.find(s=>s.id===id)).filter((s):s is Service=>Boolean(s)).slice(0,3);const q=prompt.toLowerCase();const named=services.filter(s=>`${s.name} ${s.provider} ${s.category}`.toLowerCase().includes(q));return (named.length?named:services).slice(0,3)};
const nextContributionLabel=()=>{const now=new Date();const next=now.getDate()===1?now:new Date(now.getFullYear(),now.getMonth()+1,1);return next.toLocaleDateString("en-US",{month:"short",day:"numeric"})};
const ledgerDate=(iso:string)=>{const date=new Date(iso);if(Number.isNaN(date.getTime()))return"Today";const today=new Date();if(date.toDateString()===today.toDateString())return"Today";return date.toLocaleDateString("en-US",{month:"short",day:"numeric"})};
const toUiTransaction=(row:{id:string;createdAt:string;label?:string;credits:number;kind:string}):CreditTransaction=>{const kind=row.kind==="booking"||row.kind==="package"||row.kind==="refund"||row.kind==="topup"?row.kind:"contribution";return{id:row.id,date:ledgerDate(row.createdAt),label:row.label??"Credits",credits:row.credits,kind}};
const toUiBooking=(row:Booking):Booking=>({id:row.id,serviceId:row.serviceId,serviceName:row.serviceName,provider:row.provider,date:row.date,mode:row.mode,credits:row.credits,status:row.status,packageName:row.packageName,packageItem:row.packageItem,assignment:row.assignment,proposedDate:row.proposedDate});
const assignmentNote=(b:Booking)=>b.assignment==="accepted"?" · Provider accepted":b.assignment==="proposed"?` · Provider proposed ${b.proposedDate??"a new time"}`:b.assignment==="declined"?" · Provider declined":b.assignment==="unassigned"?" · Awaiting provider":"";
const proposalToast=(booking:Booking,accepted:boolean)=>accepted?`We’ll keep ${booking.proposedDate??"this time"}. ${booking.provider} has you — Credits stay as they are.`:"Not this time. Your original hour is still waiting, and Credits stay put until you cancel.";
